import React, { useState } from 'react';
import { ListGroup, Dropdown } from 'react-bootstrap';
import AWS from 'aws-sdk';

const InputDownload = () => {
  AWS.config.update({
    accessKeyId: 'AKIA57MJGNPXRKXILUNK',
    secretAccessKey: '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',
  });

const handleClick = (e) => {
    e.preventDefault();
  };

  const handleDownload = () => {
    const s3 = new AWS.S3({region: 'us-east-2'});

    const params = {
      Bucket: 'processed-data-bucket-514-team6',
      Key: `file.txt`,
    };


    // function downloadBlob(blob, name) {
    //   // Convert your blob into a Blob URL (a special url that points to an object in the browser's memory)
    //   const blobUrl = URL.createObjectURL(blob);
    //   // Create a link element
    //   const link = document.createElement('a');
    //   // Set link's href to point to the Blob URL
    //   link.href = blobUrl;
    //   link.download = name;
    //   // Append link to the body
    //   document.body.appendChild(link);
    //   // Dispatch click event on the link
    //   // This is necessary as link.click() does not work on the latest firefox
    //   link.dispatchEvent(
    //     new MouseEvent('click', {
    //       bubbles: true,
    //       cancelable: true,
    //       view: window,
    //     })
    //   );

    //   // Remove link from body
    //   document.body.removeChild(link);
    // }

    s3.getObject(params, (err, data) => {
      if (err) {
        console.log(err, err.stack);
      } else {
        let receivedData = data.Body.toString();
        console.log(receivedData)
      }
    });

}

  return (
    <>
      <form className='bg-white my-4' onSubmit={handleClick}>
        <input
          type='submit'
          value='Download'
          className='btn btn-primary btn-block mt-3'
          onClick={handleDownload}
        />

      </form>
    </>
  );
};

export default InputDownload;
